#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int d) : data(d), left(nullptr), right(nullptr) {}
};

Node* insert(Node* node, int value) {
    if (node == nullptr) {
        return new Node(value);
    }
    if (value < node->data) {
        node->left = insert(node->left, value);
    } else {
        node->right = insert(node->right, value);
    }
    return node;
}

int height(Node* node) {
    if (node == nullptr) {
        return 0;
    }
    int leftHeight = height(node->left);
    int rightHeight = height(node->right);
    return 1 + max(leftHeight, rightHeight);
}

int depthOf(Node* root, int value) {
    int depth = 0;
    Node* cur = root;
    while (cur != nullptr && cur->data != value) {
        if (value < cur->data) {
            cur = cur->left;
        } else {
            cur = cur->right;
        }
        depth++;
    }
    return depth;
}

void destroy(Node* node) {
    if (node == nullptr) {
        return;
    }
    destroy(node->left);
    destroy(node->right);
    delete node;
}

int main() {
    Node* root = nullptr;
    int values[] = {50, 30, 70, 20, 40, 80};
    for (int i = 0; i < 6; i++) {
        root = insert(root, values[i]);
    }
    cout << "Depth of 40: " << depthOf(root, 40) << endl;
    cout << "Height: " << height(root) << endl;
    destroy(root);
    return 0;
}
